ALTER TABLE resource.rooms ADD COLUMN version integer NOT NULL DEFAULT 1 CHECK(version>0);
CREATE TABLE resource.seats(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_id uuid NOT NULL REFERENCES resource.rooms(id) ON DELETE RESTRICT ON UPDATE RESTRICT,code varchar(64) NOT NULL,socket_type varchar(16) NOT NULL DEFAULT 'NONE' CHECK(socket_type IN('NONE','FIXED','RAIL')),enabled boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(room_id,code));
CREATE TABLE resource.seat_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seat_id uuid NOT NULL REFERENCES resource.seats(id) ON DELETE RESTRICT ON UPDATE RESTRICT,occupied_period tstzrange NOT NULL,source_module varchar(8) NOT NULL CHECK(source_module IN('M1','M2')),source_id uuid NOT NULL,source_version integer NOT NULL CHECK(source_version>0),user_id uuid REFERENCES iam.users(id) ON DELETE RESTRICT ON UPDATE RESTRICT,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_module,source_id,seat_id),CHECK(NOT isempty(occupied_period) AND lower(occupied_period) IS NOT NULL AND upper(occupied_period) IS NOT NULL AND lower_inc(occupied_period) AND NOT upper_inc(occupied_period)),CHECK((source_module='M1' AND user_id IS NOT NULL) OR (source_module='M2' AND user_id IS NULL)),EXCLUDE USING gist(seat_id WITH =,occupied_period WITH &&) WHERE(active),EXCLUDE USING gist(user_id WITH =,occupied_period WITH &&) WHERE(active AND source_module='M1'));
CREATE TABLE resource.room_restrictions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),room_id uuid NOT NULL REFERENCES resource.rooms(id) ON DELETE RESTRICT ON UPDATE RESTRICT,blocked_period tstzrange NOT NULL,source_type varchar(16) NOT NULL CHECK(source_type IN('M3','ADMIN')),source_id uuid NOT NULL,source_version integer NOT NULL CHECK(source_version>0),reason text NOT NULL,active boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_type,source_id));
CREATE INDEX room_restrictions_active ON resource.room_restrictions(room_id,active);
CREATE TABLE resource.resource_operations(operation_id uuid PRIMARY KEY,source_module varchar(16) NOT NULL,source_id uuid NOT NULL,source_version integer NOT NULL CHECK(source_version>0),kind varchar(16) NOT NULL,room_id uuid REFERENCES resource.rooms(id) ON DELETE RESTRICT ON UPDATE RESTRICT,fingerprint char(64) NOT NULL,snapshot jsonb NOT NULL,applied_at timestamptz NOT NULL,replay boolean NOT NULL DEFAULT false);
CREATE INDEX resource_operations_source ON resource.resource_operations(source_module,source_id,source_version DESC);
CREATE INDEX resource_operations_history ON resource.resource_operations(room_id,applied_at);
-- A migration-time snapshot marks what is known; it does not invent earlier state history.
INSERT INTO resource.resource_operations(operation_id,source_module,source_id,source_version,kind,room_id,fingerprint,snapshot,applied_at)
SELECT gen_random_uuid(),'ADMIN',id,version,'ROOM',id,repeat('0',64),jsonb_build_object('id',id,'code',code,'name',name,'campus',campus,'building',building,'capacity',capacity,'departmentCode',department_code,'openTime',open_time,'closeTime',close_time,'bookingEnabled',booking_enabled,'enabled',enabled,'version',version),now() FROM resource.rooms;
